      famOk: ['«Игнат, как продвигается проект?» Рассветов сухо улыбается: «Ты уже заслужил „Игнат“. Продвигается. Медленно, как положено точным вещам».', '«Платоныч, глянь-ка расчёт». — «Давай. На „ты“ с теми, кто считает верно, мне не трудно».'],
      famBad: ['«Эй, Рассветов, у тебя тут допуск неправильный!» Он медленно снимает очки: «Рассветов — это на табличке. А я — Игнат Платонович. И допуск правильный».', '«Игнат, ну чё ты?» Главный инженер ледяным голосом: «Я вам не „Игнат“. Свободны».', '«Слышь, инженер…» — «Я не „слышь“. И вы — не на базаре».'],
      rg: ['Рассветов изучает цифры: «Точность — отличная. Если у вас есть рацпредложение, принесите. Я рассмотрю как можно быстрее».', '«Хороший результат. Заметно, что вы работаете головой, а не только руками».'], ro: ['«Допустимо, — произносит Рассветов. — Допуск — это не пожелание. Но и не катастрофа».'], rb: ['Рассветов качает головой: «Вы нарушаете допуски. Систематически. Это недопустимо. Не вынуждайте меня писать».', '«Цифры отвратительны. Чертежи ни при чём — они у нас в порядке. Вы — нет».']
